import { encodeCsvField } from './csv-field.mjs';

export function parseCsv(text) {
  if (typeof text !== 'string') throw new TypeError();
  if (text === '') return [];

  const rows = [];
  let row = [];
  let field = '';
  let i = 0;
  let inQuotes = false;

  const pushField = () => {
    row.push(field);
    field = '';
  };
  const pushRow = () => {
    rows.push(row);
    row = [];
  };

  while (i < text.length) {
    const c = text[i];

    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i++;
        if (i < text.length) {
          const n = text[i];
          if (n !== ',' && n !== '\r' && n !== '\n') throw new SyntaxError();
        }
        continue;
      }
      field += c;
      i++;
      continue;
    }

    if (c === '"') {
      if (field.length > 0) throw new SyntaxError();
      inQuotes = true;
      i++;
      continue;
    }

    if (c === ',') {
      pushField();
      i++;
      continue;
    }

    if (c === '\r') {
      pushField();
      pushRow();
      if (text[i + 1] === '\n') i += 2;
      else i++;
      continue;
    }

    if (c === '\n') {
      pushField();
      pushRow();
      i++;
      continue;
    }

    field += c;
    i++;
  }

  if (inQuotes) throw new SyntaxError();

  pushField();
  if (row.length > 0) pushRow();

  return rows;
}

export function serializeCsv(rows) {
  if (!Array.isArray(rows)) throw new TypeError();
  for (const row of rows) {
    if (!Array.isArray(row) || row.length === 0) throw new TypeError();
    for (const cell of row) {
      if (typeof cell !== 'string') throw new TypeError();
    }
  }
  if (rows.length === 0) return '';
  return rows.map((row) => row.map(encodeCsvField).join(',')).join('\r\n');
}

